import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

/** Total processing attempts allowed for a job that keeps failing transiently. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must lie between 250 ms and 2 s. */
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_ERROR = 'transient failure';
/** The worker counts as up if its heartbeat is at most this old. */
export const WORKER_STALE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

type Param = string | number | null;

function one(db: DatabaseSync, sql: string, ...params: Param[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string, ...params: Param[]): JobRow[] {
  return db.prepare(sql).all(...params) as unknown as JobRow[];
}

function mustOne(db: DatabaseSync, sql: string, ...params: Param[]): JobRow {
  const row = one(db, sql, ...params);
  if (!row) throw new Error(`expected a row for ${sql}`);
  return row;
}

// ---- Server-side reads and writes ----

export type SubmitOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/**
 * Creates a job, or, when `key` matches an earlier submission, returns that job (same payload) or
 * reports a conflict (different payload). The check and insert happen in one write transaction.
 */
export function submitJob(db: DatabaseSync, payload: Payload, key: string | null): SubmitOutcome {
  return transaction<SubmitOutcome>(db, () => {
    if (key !== null) {
      const existing = one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
      if (existing) {
        const same =
          existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, key, now, now);
    return { kind: 'created', row: mustOne(db, 'SELECT * FROM jobs WHERE id = ?', id) };
  });
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

export function workerIsUp(db: DatabaseSync, nowMs: number = Date.now()): boolean {
  const row = one(db, 'SELECT beat_at AS seq FROM worker_heartbeat WHERE id = 1');
  // The heartbeat timestamp is stored in the `beat_at` column; the alias above reuses JobRow's shape only for the cast.
  const beat = row ? Number((row as unknown as { seq: number }).seq) : undefined;
  return beat !== undefined && nowMs - beat < WORKER_STALE_MS;
}

// ---- Worker-side reads and writes ----

/**
 * Called once when the worker starts. Jobs left `running` by a worker that died are queued again.
 * If the interrupted attempt was the last one allowed and was set to fail, the job fails now.
 */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  return transaction(db, () => {
    const now = new Date().toISOString();
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ?
       WHERE status = 'running' AND attempts >= ? AND attempts <= fail_attempts`,
    ).run(TRANSIENT_ERROR, now, MAX_ATTEMPTS);
    const result = db
      .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`)
      .run(now);
    return Number(result.changes);
  });
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number = Date.now()): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at`,
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat').run();
}

/** Takes the oldest queued job that is due, marks it running and starts a new attempt. */
export function claimNextJob(db: DatabaseSync): JobRow | undefined {
  return transaction<JobRow | undefined>(db, () => {
    const next = one(
      db,
      `SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1`,
      Date.now(),
    );
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?`,
    ).run(new Date().toISOString(), next.seq);
    return mustOne(db, 'SELECT * FROM jobs WHERE seq = ?', next.seq);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`).run(
    completed,
    new Date().toISOString(),
    id,
  );
}

/** Returns a job to `queued` so that it can be claimed again once `runAfterMs` has passed. */
export function requeueJob(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(runAfterMs, new Date().toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  const now = new Date().toISOString();
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL,
       progress_completed = steps, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(output, now, id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(error, new Date().toISOString(), id);
}

