import type { Payload } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type Submission = { ok: true; payload: Payload; key: string | null } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

function intField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return value;
}

/**
 * Validates a job submission: the Content-Type, the JSON body, and the Idempotency-Key header.
 * Every offending field is reported, not just the first.
 */
export function validateSubmission(
  contentType: string | undefined,
  rawBody: string,
  idempotencyKey: string | undefined,
): Submission {
  const fields: FieldError[] = [];

  const media = contentType?.split(';')[0]?.trim().toLowerCase();
  if (media !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }

  if (idempotencyKey !== undefined && !KEY_PATTERN.test(idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;

  if (media === 'application/json') {
    let parsed: unknown;
    let parseFailed = false;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      parseFailed = true;
    }
    if (parseFailed) {
      fields.push({ field: 'body', message: 'Request body must be valid JSON.' });
    } else if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      fields.push({ field: 'body', message: 'Request body must be a JSON object.' });
    } else {
      const obj = parsed as Record<string, unknown>;
      for (const key of Object.keys(obj)) {
        if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
      }

      if (!Object.hasOwn(obj, 'input')) {
        fields.push({ field: 'input', message: 'Required.' });
      } else if (typeof obj.input !== 'string') {
        fields.push({ field: 'input', message: 'Must be a string.' });
      } else if (obj.input.length < 1 || obj.input.length > 1000) {
        fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
      } else if (obj.input.trim() === '') {
        fields.push({ field: 'input', message: 'Must not be only whitespace.' });
      } else {
        input = obj.input;
      }

      steps = intField(obj, 'steps', 1, 20, 5, fields);
      failAttempts = intField(obj, 'failAttempts', 0, 5, 0, fields);
    }
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, payload: { input, steps, failAttempts }, key: idempotencyKey ?? null };
}

