import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, listJobs, submitJob, toJob, workerIsUp } from './jobs.ts';
import { validateSubmission, type FieldError } from './validate.ts';

/** Largest request body accepted. A 1000-character input with every character escaped is well under this. */
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

/** Reads the request body. Resolves to null when the body exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  if (raw === null) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', [
      { field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` },
    ]);
  }
  const key = req.headers['idempotency-key'];
  const submission = validateSubmission(req.headers['content-type'], raw, typeof key === 'string' ? key : undefined);
  if (!submission.ok) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', submission.fields);
  }
  const outcome = submitJob(db, submission.payload, submission.key);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`, undefined, {
    allow: allowed.join(', '),
  });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: workerIsUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJob) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const id = decodeURIComponent(match[1]!);
    const row = getJob(db, id);
    if (!row) return sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return send(res, 200, toJob(row));
  }

  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, 2_000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

